# region: fold
def fold(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: render
def render(xs, factor=2):
    return [v * factor for v in xs]

# region: emit
def emit(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: gather
def gather(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return gather(emit(render(fold(raw))))

